GROUP_KINDS = ["department", "committee", "external"]


def move_contact_person(apps, schema_editor):
    """Each existing point of contact becomes the main contact of that department."""
    Holder = apps.get_model("tracker", "Holder")
    Contact = apps.get_model("tracker", "Contact")
    for h in Holder.objects.exclude(contact_person=""):
        if h.kind in GROUP_KINDS:
            Contact.objects.create(holder=h, name=h.contact_person.strip(), is_primary=True)


def restore_contact_person(apps, schema_editor):
    Holder = apps.get_model("tracker", "Holder")
    Contact = apps.get_model("tracker", "Contact")
    for c in Contact.objects.filter(is_primary=True):
        Holder.objects.filter(pk=c.holder_id).update(contact_person=c.name[:120])


